  'settings.handwriting': 'Handwriting',
  'settings.handwritingNative': 'This app captures your writing with the device’s own ink surface, using a stylus or your finger. Your handwriting is read by Pri’s server reader below, which needs a connection and a signed-in account. Your ink stays on this device; when an answer is marked, its original is also kept with the mark for 2 years, as the privacy notice describes.',
  'settings.handwritingBrowser': 'Write with your finger, a stylus or a mouse. Your handwriting is read by Pri’s server reader below, which needs a connection and a signed-in account. Your ink stays on this device; when an answer is marked, its original is also kept with the mark for 2 years, as the privacy notice describes.',
  'settings.cloudOnFor': '{label} is on for this profile',
  'settings.cloudOffFor': '{label} is off — this stays on your device',

  // Consent copy. These six say what leaves the device, and a student cannot
  // consent to something they cannot read — which is the whole reason they are
  // in the catalogue rather than left in English "to be safe". They are also
  // the strings in this file where a mistranslation would do real harm, so the
  // Hindi is flagged for native legal review in strings.hi.js.
  'settings.cloudHandwritingLabel': 'Read my handwriting and photos on the server',
  'settings.cloudHandwritingUnavailable': 'Reading handwriting and photos needs Pri’s server, which is not available here right now. Your ink is still kept on this device.',
  'settings.cloudHandwritingCopy': 'Handwriting and photos are read only by this server reader; the on-device reader is not accurate enough to mark from. It is on by default for a signed-in account, and you can turn it off here — but then handwriting and photos are not read at all, and you type your answers instead. While it is on, a picture drawn from your strokes or your photo is sent through Pri’s server to an outside AI reading service to be read. It is a picture of your writing only — never the question, never the answer, never your name. Pri does not keep that picture just for reading; when you then submit the answer to be marked, Pri keeps your original handwriting or photo with the mark for 2 years, as the privacy notice describes. The reading service is asked not to store it, but may hold it for a limited time under its own safety-monitoring rules. The reading only proposes what you wrote: Pri’s own marker decides the mark.',
  'settings.cloudMarkingLabel': 'Tell me which line my working went wrong on',
  'settings.cloudMarkingUnavailable': 'Checking working line by line on a server is not available on this install.',
  'settings.cloudMarkingCopy': 'When an answer is wrong and Pri cannot tell you where, turn this on and your working is checked line by line. It says which line broke and what kind of mistake it was — and if you slipped once and then worked correctly from your own wrong number, it says that too, instead of marking you wrong five times for one mistake. Your question and your working are sent; the expected answer never is, and it will not tell you the answer. Your mark is decided by Pri’s deterministic marker on the server either way and does not change.',

  'settings.appearance': 'Appearance',
  'settings.themeDark': 'Night',
  'settings.themeLight': 'Paper',
  'settings.themeSystem': 'Match device',
  'settings.themeNote': 'Paper is the default: dark ink on a light page is easiest to read for long sessions. Night is the same notebook with the lamp turned down.',
  'settings.themeSystemNote': 'Pri follows this device: paper when the device is in light mode, night when it is in dark mode.',

  'settings.courses': 'Courses',
  'settings.enrolled': 'Enrolled',
  'settings.coursesNote': 'Questions are issued by Pri’s server and mapped to your syllabus’s naming — changing year or pathway in Profile re-scopes Smart Practice, exams and priorities instantly.',

  'settings.dataBackup': 'Data & Backup',
  'settings.dataNote': 'One JSON file holds everything — profile, ratings, attempts, exams, handwriting. Restore it on any device to pick up where you left off. The file itself is not encrypted and a restored profile comes back without its password, because a backup carries no password verifier — set one again after restoring to re-protect it. Keep the file somewhere you would be happy to keep a notebook. Progress files are small summaries you can share with a teacher, who imports them into class analytics.',
  'settings.exportBackup': 'Export full backup',
  'settings.restoreBackup': 'Restore from backup',
