  'settings.backupRestoredUnprotected': 'Backup restored — {rows} records. This profile has no password; set one in Account to protect it again.',
  'settings.deleteProfile': 'Delete this profile…',
  'settings.deleteWarning': 'Deleting “{name}” wipes its ratings, attempts, exams, favourites and handwriting from this device. Nothing is held anywhere else — export a full backup first if there is any chance you want it back.',
  'settings.typeNameToConfirm': 'Type “{name}” to confirm',
  'settings.typeNameLabel': 'Type {name} to confirm deletion',
  'settings.typeTheName': 'Type the profile name — “{name}” — to confirm.',
  'settings.enterPasswordToDelete': 'Enter this profile’s password to delete it.',
  'settings.deleting': 'Deleting…',
  'settings.reallyDelete': 'Really delete “{name}” and all its data',

  'settings.helpSafety': 'Help & Safety',
  'settings.helpBodyIndia': 'Each chapter tracks a skill rating that moves with each answer — harder questions move it more. Smart Practice targets ~70% success and weaves in spaced reviews before topics fade. The mark estimate covers only the parts of the paper you have practised, and it never converts that into a CBSE percentage, a JEE percentile or a rank — none of those can be honestly derived from practice at home. Handwritten answers are read by Pri’s server reader when you are online, then marked by the same engine as typed answers, line by line. Hints and retries still earn credit, just a little less.',
  'settings.helpBody': 'Every subtopic tracks a skill rating that moves with each answer — harder questions move it more. Smart Practice targets ~70% success, weaves in spaced reviews before topics fade, and the mark estimate covers only the parts of the paper you have actually practised. Handwritten answers are read by Pri’s server reader when you are online, then marked by the same engine as typed answers, line by line. Hints and retries still earn credit, just a little less.',
  'settings.addToHomeScreen': ' For a full-screen app: use your browser’s “Add to Home Screen”.',

  // ── Sign-in and onboarding ─────────────────────────────────────────────────
  // Public account entry and explicit offline entry are load-bearing browser contracts.
