  'login.createNote': 'No verification email, no reset link, no one to ask: a profile is a record on this device and nowhere else. A password keeps it to yourself — stored as a salted hash in the device’s own storage, never uploaded, and only you can lift it. Before anything opens, the profile is connected to your Pri account, which keeps your progress on every device you sign in on.',
  'login.authFoot': 'Profiles, progress and handwriting live in this device’s storage. Nothing leaves the device unless you sign in to a Pri cloud account, which is what checks your answers. No ads.',

