  'placement.title': 'Placement check',
  'placement.introLead': 'About 10 questions — never more than 12 — to estimate where you are working and trace a likely gap back to where it may start.',
  'placement.introHow': 'It starts at your class. A miss sends the next question down to the topic it builds on; a clean answer sends it up. Answer in your own handwriting, or type if you prefer.',
  'placement.introMarking': 'Every answer is marked by Pri’s deterministic marker — the same one practice uses. No AI decides a mark.',
  'placement.introEvidence': 'The result is diagnostic evidence from a handful of questions, not a mastery score. It never changes your XP, streak or practice history. It does reorder smart practice for chapters you have not practised yet: chapters where it found a gap come earlier and start at an easier level. You can retake it any time.',
